    statusUpdates: ["Reading your message", "Opening a fresh JUMPINGGOOSE thread"],
    sessionId: d.sessionId || "default_session",
    memory: d.currentMemory || {},
    sessionSummary: ""
  }
}];

const d = $input.first().json || {};
