estions":{"M1":"What is the communication objective: awareness, consideration, conversion, loyalty, or trust?","M2":"What single message should feel true across everything?","M3":"Which channels matter most?"}},"SOCIAL_ADDON":{"triggers":["social","instagram","linkedin","post","reel","caption","calendar","ugc"],"questions":{"S1":"Which social platform matters most right now?","S2":"What should the audience do after seeing the content?","S3":"What content formats are realistic for the team to produce consistently?"}},"REBRANDING_ADDON":{"triggers":["rebrand","refresh","evolve","change","broken"],"questions":{"R1":"Why is the brand changing now?","R2":"What must stay sacred through the change?","R3":"What audience perception needs to shift?"}}},
    research_context: { query: "", abstract: "", source: "", url: "", related: [] },
    statusUpdates: d.statusUpdates || ["Thinking through your request", "Preparing brand discovery questions"],
    selectedReferenceKinds: ["questionnaireReference"]
  }
}];

