const raw = $input.first()?.json || {};
const content = raw.choices?.[0]?.message?.content || "{}";
let parsed;
try {
  parsed = JSON.parse(content.replace(/^```json\s*/i, "").replace(/```$/i, "").trim());
} catch (error) {
  parsed = {};
}
const initialAction = String($node["Conversation Gate"].json.initial_action_type || "").toUpperCase();
const action = String(parsed.action_type || initialAction || "GENERAL").toUpperCase();
const allowed = ["DISCOVERY", "STRATEGY", "COMMS", "SOCIAL", "COPY", "GENERAL", "FEEDBACK"];
const gate = $node["Conversation Gate"].json || {};
const needsWebResearch = Boolean(gate.needsWebResearch || (parsed.needs_web_research && parsed.research_query));
const researchQuery = parsed.research_query || gate.research_query || $node["Standardize Input"].json.userInput;
return [{
  json: {
    ...parsed,
    action_type: allowed.includes(action) ? action : "GENERAL",
    needsWebResearch,
    research_query: researchQuery,
    statusUpdates: gate.statusUpdates || ["Thinking through your request", "Finding the right JUMPINGGOOSE agent"],
    userInput: $node["Standardize Input"].json.userInput,
    sessionId: $node["Standardize Input"].json.sessionId,
    currentMemory: $node["Standardize Input"].json.currentMemory,
    feedback: $node["Standardize Input"].json.feedback
  }
}];

const d = $input.first().json || {};
const action = String(d.action_type || "GENERAL").toUpperCase();

const references = {
  questionnaireReference: {"INTRO":{"triggers":["new brand","start","hello","hi","begin","brand name"],"questions":{"I1":"What is your brand name?","I2":"What type of project are we working on? Brand Strategy, Brand Communication, Social Content, Copywriting, Rebranding, or General Brand Help?","I3":"What category does the brand operate in?"}},"CORE_IDENTITY":{"triggers":["conviction","belief","purpose","why","mission","values"],"questions":{"C1":"What is the one conviction that drives your brand? Not a tagline, the belief behind everything.","C2":"When your brand fulfils its promise, what changes in your customer's life?"}},"CORE_AUDIENCE":{"triggers":["customer","audience","target","buyer","persona","demographic"],"questions":{"C3":"Describe one person who needs this brand the most: age, city, context, and day-in-life.","C4":"What does your customer actively avoid? Brands, messages, behaviours, or tones they would reject."}},"CORE_COMPETITION":{"triggers":["competitor","competition","differentiation","unique","better"],"questions":{"C5":"Who are your top 3 competitors, and where are they strong or weak?","C6":"What is the one specific thing you do better or differently?"}},"CORE_PERSONALITY":{"triggers":["personality","tone","voice","character","vibe","feel","words"],"questions":{"C7":"Pick 5 words that must describe your brand, and 5 words that must never describe it.","C8":"Give me one sentence your brand would say, and one it would never say.","C9":"If the brand were a person in a room, how would it behave?"}},"CORE_POSITIONING":{"triggers":["reference","aspiration","price","positioning","channel","timeline","goals"],"questions":{"C10":"Who is an aspirational reference brand and what do you admire about them?","C11":"What is the price positioning: budget, value, mid-premium, premium, or luxury?","C12":"What are the top 3 business goals for the next 12 months?"}},"COMMS_ADDON":{"triggers":["campaign","message","channel","content","format","asset","launch"],"questions":{"M1":"What is the communication objective: awareness, consideration, conversion, loyalty, or trust?","M2":"What single message should feel true across everything?","M3":"Which channels matter most?"}},"SOCIAL_ADDON":{"triggers":["social","instagram","linkedin","post","reel","caption","calendar","ugc"],"questions":{"S1":"Which social platform matters most right now?","S2":"What should the audience do after seeing the content?","S3":"What content formats are realistic for the team to produce consistently?"}},"REBRANDING_ADDON":{"triggers":["rebrand","refresh","evolve","change","broken"],"questions":{"R1":"Why is the brand changing now?","R2":"What must stay sacred through the change?","R3":"What audience perception needs to shift?"}}},
  strategyFrameworks: {"EQUATION_OF_TRUTH":{"triggers":["truth","intersection","consumer","product truth","brand truth"],"framework":"Consumer Truth (drivers, fears, aspirations) + Product Truth (craft, advantages) = Brand Truth (the ownable intersection)."},"GOLDEN_CIRCLE":{"triggers":["why","purpose","how","what"],"framework":"Why -> How -> What. Start with belief, then method, then product."},"ARCHETYPE_PAIRING":{"triggers":["archetype","personality","character","persona"],"framework":"Select Primary Archetype + Secondary Archetype, then define behaviour, voice, and proof."},"BRAND_PILLARS":{"triggers":["pillar","foundation","principle","value prop"],"framework":"4-6 strategic pillars with rationale, proof points, and expression guidelines."},"POSITIONING":{"triggers":["positioning","statement","differentiation","category"],"framework":"For [target], [brand] is the [category] that [differentiation] because [reasons to believe]."},"MANIFESTO":{"triggers":["manifesto","anthem","story","soul","narrative"],"framework":"A belief-led narrative that captures the brand's point of view, tension, promise, and invitation."}},
  communicationFrameworks: {"CAMPAIGN_STRATEGY":{"triggers":["campaign","kpi","objective","awareness","conversion"],"framework":"Objective and KPIs -> Audience segments -> Message hierarchy -> Channel roles -> Execution rhythm."},"CONTENT_ARCHITECTURE":{"triggers":["content","calendar","pillar","cadence","format"],"framework":"Content pillars -> Series ideas -> Cadence -> Format recommendations -> Measurement."},"SIX_PILLAR_SOCIAL":{"triggers":["social","instagram","post","reel","engagement","ugc"],"framework":"6 pillars: Brand Posts, Product Posts, Engagement Posts, Moment Posts, Announcement Posts, Culture Posts."},"CAMPAIGN_TERRITORIES":{"triggers":["territory","direction","idea","concept","hashtag"],"framework":"Territory name -> Core idea -> Message hook -> Content series -> Hashtag -> Platform priority."},"BRAND_COMMS_GUIDELINES":{"triggers":["guidelines","dos","donts","crisis","pr","media","stakeholder"],"framework":"Messaging dos/donts -> Stakeholder templates -> PR guidance -> Crisis response principles."}},
